cd /Users/marcel.a.n.navarro/Downloads
find . -maxdepth 2 -type d -not -path './.claude/_archived*' -not -path './Pre-Zimm/*' | sort | sed 's|^\./||' | awk -F/ '{
  indent=""; for(i=1;i<NF;i++) indent=indent"   ";
  n=split($0,a,"/"); print indent a[n]"/"
}' | sed '1s|.*|~/Downloads/|'
echo
echo "=== file counts per top-level folder ==="
for d in _Inbox _Review Accenture-Admin Learnings Media Personal Playbooks Pre-Zimm Zimmermann-PWA; do
  printf "  %-18s %3s files  %6s\n" "$d" "$(find "$d" -type f | wc -l | tr -d ' ')" "$(du -sh "$d" | cut -f1)"
done
